body { font: 14px/1.5 sans-serif; margin: 0; color: #202124; }
header { position: sticky; top: 0; background: #fff; display: flex; gap: 24px;
         align-items: center; padding: 12px 16px; border-bottom: 1px solid #ddd; }
header input { width: 480px; padding: 8px 16px; border: 1px solid #ccc; border-radius: 24px; }
nav.tabs { display: flex; gap: 20px; padding: 4px 150px; border-bottom: 1px solid #eee; }
main { display: flex; gap: 64px; padding: 0 150px; }
.results { width: 600px; }
.result { margin: 24px 0; }
.site { display: flex; gap: 8px; align-items: center; font-size: 12px; }
.site img { width: 18px; height: 18px; border-radius: 50%; }
.site cite { color: #4d5156; font-style: normal; }
.result h3 { margin: 4px 0; font-size: 20px; font-weight: 400; }
.result h3 a { color: #1a0dab; text-decoration: none; }
.ask button { display: block; width: 100%; text-align: left; padding: 12px 0;
              border: 0; border-top: 1px solid #ddd; background: none; font: inherit; }
.ask [hidden] { display: none; }
aside { width: 360px; border: 1px solid #ddd; border-radius: 8px; padding: 16px; margin-top: 24px; }
aside img { width: 100%; height: 160px; object-fit: cover; }
footer { display: flex; gap: 12px; padding: 24px 150px; }

for (const b of document.querySelectorAll('.ask button')) {
  b.addEventListener('click', () => {
    const open = b.getAttribute('aria-expanded') !== 'true';
    b.setAttribute('aria-expanded', String(open));
    document.getElementById(b.getAttribute('aria-controls')).hidden = !open;
  });
}
